    isThisWeek:1,
})
// 初始化组件
onMounted(() => {
  const uus = localStorage.getItem('auuids')
  if(uus){
      date.value = userTime.dateNow();
      getUserwin();
      getTwoBet();
  }
})
const goToReport = (date) => {
  router.push(`/settlementReport?date=${date}`)
}
const getWeek = (dateString) =>{
  const weekdays = ['日', '一', '二', '三', '四', '五', '六'];
  const date = new Date(dateString.replace(/-/g, '/'));
  const year = date.getFullYear();
  const month = date.getMonth();
  const day = date.getDate();
  const weekdayIndex = new Date(year, month, day).getDay();
  return weekdays[weekdayIndex];
}
// 可用额度
const getUserwin = async() =>{
  try {
    let res = await userStore.getTodaySwings();
    useful.value = res.data;
  } catch (error) {
     console.log('获取盈亏失败')
  }
}
const twoBack = () =>{
    router.push({
        path: `/ReportQuery`
    })
}
const toweks = (item) =>{
    let tps = {
        start:'',
        end:'',
        accountId:'',
        lotteryList:[],
        type:1,
        status:2,
        account:'',
        credit:'',
        win:'',
        period:'',
        playCountType:1,
        isacout:2,
        twops:1,
    };
    tps.start = item.day + ' 07:00:00';
    let dats = new Date(item.day);
    dats.setDate(dats.getDate()+1);
    let tt = formatTime(dats);
    tps.end   = tt + ' 06:59:59';
    let params = JSON.parse(JSON.stringify(tps));
    router.push({name: 'ReportList', params: params})
}
const formatTime = (date)  => {
    const year = date.getFullYear();
    const month = (date.getMonth()+1) < 10 ? '0'+(date.getMonth()+1) : date.getMonth()+1;
    const day =  date.getDate()< 10 ? '0'+date.getDate(): + date.getDate();
    return `${year}-${month}-${day}`
}
const neTab = (num) =>{
    param.value.isThisWeek = num;
    currweek.value = [];
    getTwoBet();
}
// 获取列表
const getTwoBet = async() =>{
  try {
    loading.value = true;
    let res = await userStore.twoweeks(param.value);
    currweek.value = res.data;
    let t1 = 0;
    let t2 = 0;
    let t3 = 0;
    let t4 = 0;
    let t5 = 0;
    currweek.value.forEach(item=>{
        t1 += parseFloat(item.belongResult);
        t2 += parseFloat(item.belongSettlement);
        t3t += parseInt(item.belongWin);
        t4 += parseFloat(item.belongReback);
